from collections import deque

def solve_board(n, initial_state):
    """
    Attempts to clear the n x n board starting from initial_state using BFS.
    State is represented as a tuple of tuples (immutable).
    """
    # Target state is all zeros
    target_state = tuple([tuple([0] * n) for _ in range(n)])

    if initial_state == target_state:
        return True, []

    queue = deque([(initial_state, [])])  # (state, path)
    visited = {initial_state}

    while queue:
        current_state, path = queue.popleft()
        board = [list(row) for row in current_state]

        # --- Check for possible moves ---
        next_moves = []

        # 1. L-shaped tromino placement (Fixed orientation: (r,c), (r+1,c), (r,c+1))
        # Iterate through possible top-left corners (r, c)
        for r in range(n - 1):
            for c in range(n - 1):
                # Cells involved: (r, c), (r+1, c), (r, c+1)
                cells = [(r, c), (r+1, c), (r, c+1)]

                # Check if all cells are empty (0)
                if all(board[r_i][c_i] == 0 for r_i, c_i in cells):
                    new_board = [row[:] for row in board]
                    for r_i, c_i in cells:
                        new_board[r_i][c_i] = 1

                    new_state = tuple(tuple(row) for row in new_board)
                    next_moves.append((new_state, f"Place_L_{r},{c}"))

        # 2. Column clear
        for c in range(n):
            is_full = all(board[r][c] == 1 for r in range(n))
            if is_full:
                new_board = [row[:] for row in board]
                for r in range(n):
                    new_board[r][c] = 0

                new_state = tuple(tuple(row) for row in new_board)
                next_moves.append((new_state, f"Clear_Col_{c}"))

        # 3. Row clear
        for r in range(n):
            is_full = all(board[r][c] == 1 for c in range(n))
            if is_full:
                new_board = [row[:] for row in board]
                for c in range(n):
                    new_board[r][c] = 0

                new_state = tuple(tuple(row) for row in new_board)
                next_moves.append((new_state, f"Clear_Row_{r}"))


        # Process generated moves
        for next_state, move_name in next_moves:
            if next_state == target_state:
                return True, path + [move_name]

            if next_state not in visited:
                visited.add(next_state)
                queue.append((next_state, path + [move_name]))

    return False, None

# --- Testing n = 2, 3, 4 ---

# Initial state: empty board
initial_empty = tuple([tuple([0] * n) for n in [2, 3, 4]])

